<script lang="ts">
import {getContext} from 'svelte';import PageHeader from '#lib/components/PageHeader.svelte';import UiBanner from '#lib/components/UiBanner.svelte';import {createPickingBatchesState} from '../state/pickingBatchesState.svelte';import type {PickingBatch} from '../../domain/entity/PickingBatch';
const vm=createPickingBatchesState();const warehouse=getContext<{warehouseId:number|null}>('warehouseSelection');let search=$state(''),target=$state<PickingBatch|null>(null),actionError=$state(''),success=$state('');
const rows=$derived.by(()=>{const q=search.trim().toLowerCase();return vm.rows.filter(x=>!q||[x.batchNumber,x.assignedTo??'',x.transferOrderNumber??'',...x.orders].some(v=>v.toLowerCase().includes(q)));});
let seen:number|null|undefined=undefined;$effect(()=>{const id=warehouse?.warehouseId??null;if(id===seen)return;seen=id;target=null;void vm.load(id);});
function date(v:string|null){if(!v)return '—';const d=new Date(v);return Number.isNaN(d.getTime())?v:d.toLocaleString();}
async function release(){if(!target||vm.saving)return;const row=target;const result=await vm.release(row);if(!result){actionError=vm.error??'No se pudo liberar el lote';return;}target=null;actionError='';success=result.releasedOrders.length?`Lote ${row.batchNumber} liberado. Pedidos liberados: ${result.releasedOrders.join(', ')}.`:`Lote ${row.batchNumber} liberado.`;await vm.load(warehouse?.warehouseId??null);}
</script>
<section class="page"><PageHeader title="Picking Batches" subtitle="Administra los lotes activos y libera pedidos retenidos por una sesión de picking interrumpida."/>
{#if success}<UiBanner tone="success" message={success}/>{/if}{#if vm.error}<UiBanner tone="error" message={vm.error}/>{/if}
<section class="panel"><div class="toolbar"><label>Buscar lote, pedido, transferencia o picker<input type="search" bind:value={search} placeholder="Batch, SO, TO o picker"/></label><button class="secondary" onclick={()=>void vm.load(warehouse?.warehouseId??null)} disabled={vm.loading}>{vm.loading?'Actualizando…':'Actualizar'}</button><span>{rows.length} lotes</span></div>
{#if warehouse?.warehouseId==null}<p class="empty">Selecciona un almacén.</p>{:else if vm.loading}<p class="empty">Cargando lotes…</p>{:else if vm.error}<p class="empty">No se pudieron cargar los lotes.</p>{:else if rows.length===0}<p class="empty">{search.trim()?'No hay coincidencias.':'No hay lotes OPEN o IN_PROGRESS en este almacén.'}</p>{:else}
<div class="table-wrap"><table><thead><tr><th>Lote</th><th>Tipo</th><th>Pedidos / transferencia</th><th>Picker</th><th>Progreso</th><th>Creado</th><th>Estado</th><th></th></tr></thead><tbody>
{#each rows as row (row.batchId)}<tr><td class="mono"><a href={'/picking-batches/'+row.batchId}>{row.batchNumber}</a></td><td>{row.kind}</td><td>{#if row.kind==='TO'}<span class="mono">{row.transferOrderNumber??'—'}</span>{:else if row.orders.length}{#each row.orders as so}<div class="mono">{so}</div>{/each}{:else}<span class="muted">Sin pedidos asociados</span>{/if}</td><td>{row.assignedTo??'—'}</td><td class="mono">{row.completedTasks}/{row.totalTasks}<small>{row.pendingTasks} pendientes</small></td><td>{date(row.createdAt)}</td><td><span class="status">{row.status}</span></td><td>{#if row.kind==='SO'}<button class="danger small" onclick={()=>{target=row;actionError='';}}>Liberar</button>{:else}<button class="secondary small" disabled title="Gestionar desde Órdenes de traslado">Solo lectura</button>{/if}</td></tr>{/each}
</tbody></table></div>{/if}<p class="hint">Solo se listan lotes OPEN e IN_PROGRESS. Los lotes TO son de solo lectura en esta pantalla.</p></section></section>
{#if target}<div class="backdrop"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="confirm-title"><h2 id="confirm-title">¿Liberar {target.batchNumber}?</h2><p>Se cancelará el lote, se liberarán las reservas pendientes y las unidades ya recogidas volverán a sus ubicaciones de origen en el WMS. Los pedidos asociados podrán prepararse de nuevo.</p>{#if target.orders.length}<strong>Pedidos afectados</strong>{#each target.orders as so}<div class="mono">{so}</div>{/each}{/if}<p class="warning">La devolución en el sistema no devuelve físicamente los artículos al estante. El picker debe realizar esa devolución física.</p>{#if actionError}<UiBanner tone="error" message={actionError}/>{/if}<div class="actions"><button class="secondary" onclick={()=>target=null} disabled={vm.saving}>Conservar lote</button><button class="danger" onclick={()=>void release()} disabled={vm.saving}>{vm.saving?'Liberando…':'Confirmar liberación'}</button></div></div></div>{/if}
<style>
.page{padding:1.25rem;max-width:96rem;margin:auto;color:var(--ink)}.panel{background:var(--surface);border:1px solid var(--line);border-radius:1rem;padding:1rem}.toolbar{display:flex;align-items:end;gap:.75rem;flex-wrap:wrap;margin-bottom:1rem}.toolbar label{display:flex;flex:1 1 22rem;flex-direction:column;gap:.35rem;font-size:.8rem;color:var(--slate)}input[type=search]{min-height:2.45rem;padding:.5rem .7rem;border:1px solid var(--line);border-radius:.55rem;background:var(--surface);color:var(--ink)}button{border:1px solid var(--navy);background:var(--navy);color:white;border-radius:.55rem;padding:.55rem .85rem;cursor:pointer;font-weight:600}button:disabled{opacity:.55;cursor:not-allowed}button.secondary{background:var(--surface);color:var(--ink);border-color:var(--line)}button.danger{background:#a52c35;border-color:#a52c35}button.small{padding:.38rem .6rem;font-size:.78rem}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;font-size:.84rem}th,td{text-align:left;padding:.72rem .65rem;border-bottom:1px solid var(--line);vertical-align:top}th{font-size:.72rem;text-transform:uppercase;color:var(--slate);white-space:nowrap}td a{color:var(--navy);font-weight:650;text-decoration:none}.mono{font-family:var(--mono,monospace);font-size:.82rem}td small{display:block;color:var(--slate)}.status{border-radius:999px;padding:.2rem .5rem;background:color-mix(in srgb,var(--navy) 10%,transparent);font-size:.7rem;font-weight:700}.muted,.hint{color:var(--slate)}.empty{text-align:center;padding:2rem;color:var(--slate)}.hint{font-size:.75rem;margin-top:.9rem}.backdrop{position:fixed;inset:0;z-index:500;background:#10192388;display:grid;place-items:center;padding:1rem}.modal{width:min(34rem,100%);background:var(--surface);border:1px solid var(--line);border-radius:1rem;padding:1.35rem}.modal h2{font-size:1.2rem}.warning{padding:.65rem;border-left:3px solid #b7791f;background:color-mix(in srgb,#b7791f 9%,transparent);font-size:.82rem}.actions{display:flex;justify-content:flex-end;gap:.6rem;margin-top:1rem}@media(max-width:760px){.page{padding:.8rem}table{min-width:850px}}
</style>